offerReady.then(({brands,promotions})=>{
const U=OFFER;const title=(name,sub,href)=>'<div class="section-heading"><h2>'+name+'<span>'+sub+'</span></h2><a class="text-link" href="'+href+'">전체 보기 '+U.icon('arrow')+'</a></div>';
const featured=promotions.filter(p=>p.featured).slice(0,3);const usedImages=new Set();const fresh=[...promotions].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).filter(p=>{if(usedImages.has(p.image))return false;usedImages.add(p.image);return true;}).slice(0,4);const ending=promotions.filter(U.active).sort((a,b)=>U.remaining(a)-U.remaining(b)).slice(0,3);
const main=document.getElementById('main');main.classList.add('home-layout');main.innerHTML='<section id="home-hero" class="container hero" aria-labelledby="hero-heading"><div class="hero-topline eyebrow"><span>THE OFFER EDIT</span><span class="edition">THE AUTUMN EDIT · 2026</span></div><h1 id="hero-heading">Find your next <em>OFFER.</em></h1><p class="hero-copy">지금 받을 수 있는 브랜드의 혜택을 발견하세요.</p>'+U.searchForm('','home-search')+'<div class="hero-index"><strong>'+brands.length+'</strong>BRANDS · ONE PLACE</div></section><section id="home-popular" class="container section home-popular">'+title('Popular OFFER','지금 눈여겨볼 혜택','explore.html?sort=popular')+('<div class="offer-grid--editorial">'+featured.map((p,i)=>U.card(p,i===0?'featured':'supporting')).join('')+'</div>')+'</section><section id="home-new" class="container section new-section">'+title('New OFFER','새롭게 발견한 혜택','explore.html?sort=new')+U.grid(fresh)+'</section><div id="home-ending" class="ending-section"><section class="container section">'+title('Ending Soon','놓치기 전에 확인하세요','explore.html?sort=ending')+(ending.length?U.grid(ending,true,'deadline'):U.empty('곧 종료되는 OFFER가 없습니다.','다른 브랜드의 혜택을 둘러보세요.'))+'</section></div><section id="home-categories" class="container section"><div class="section-heading"><h2>Explore by Category</h2></div><div class="category-list">'+[['fashion','Fashion'],['beauty','Beauty'],['food','Food'],['lifestyle','Lifestyle']].map(([id,label])=>'<a class="category-link" href="explore.html?category='+id+'"><span>'+label+'<small>'+promotions.filter(p=>p.category===id).length+' OFFERs</small></span>'+U.icon('up')+'</a>').join('')+'</div></section><section id="home-following" class="container section following-section"><div class="section-heading"><h2>Brands You Follow</h2><a class="text-link" href="favorites.html">관심 브랜드 '+U.icon('arrow')+'</a></div><div id="following-content"></div></section>';
main.querySelector('.hero-copy').textContent='여러 브랜드의 혜택을 한곳에서. 지금 나에게 맞는 OFFER를 찾아보세요.';
main.querySelector('#home-hero .search-form').insertAdjacentHTML('afterend','<nav class="hero-shortcuts" aria-label="빠른 카테고리 탐색"><span>바로 찾기</span><a href="explore.html?category=fashion">Fashion</a><a href="explore.html?category=beauty">Beauty</a><a href="explore.html?category=food">Food</a><a href="explore.html?category=lifestyle">Lifestyle</a></nav>');
function renderFollowing(){const followed=U.read('favoriteBrands');const items=promotions.filter(p=>followed.includes(p.brandId)&&U.active(p));document.getElementById('following-content').innerHTML=items.length?U.grid(items.slice(0,4)):followed.length?U.empty('새로운 OFFER를 기다리고 있어요.','관심 브랜드에 현재 진행 중인 OFFER가 없습니다.'):'<div class="empty-state"><div><h3>취향이 모이면, 나만의 OFFER.</h3><p>좋아하는 브랜드를 팔로우하고 나만의 혜택 피드를 만들어보세요.</p><div class="brand-suggestions">'+brands.filter(b=>['musinsa','nike','oliveyoung','29cm'].includes(b.id)).map(b=>U.followButton(b,true)).join('')+'</div></div><a class="text-link" href="favorites.html">브랜드 둘러보기 '+U.icon('arrow')+'</a></div>';}
// Reorder the actual DOM so keyboard and visual reading order agree on mobile.
const mobile=matchMedia('(max-width: 767px)');
function arrangeSections(){const focused=document.activeElement;const order=mobile.matches?['hero','popular','ending','categories','new','following']:['hero','popular','new','ending','categories','following'];order.forEach(name=>main.appendChild(document.getElementById('home-'+name)));if(focused&&main.contains(focused))focused.focus({preventScroll:true});}
arrangeSections();mobile.addEventListener('change',arrangeSections);
renderFollowing();document.addEventListener('offer:storage',e=>{if(e.detail.key==='favoriteBrands')renderFollowing();});document.addEventListener('offer:external-storage',renderFollowing);
});
